import React, { useState } from "react";


function Analyzer() {

  const [requirement, setRequirement] = useState("");
  const [result, setResult] = useState(null);


  const analyzeRequirement = () => {

    setResult({
      impact: "High",
      modules: [
        "Authentication Module",
        "Payment Module",
        "Database Module"
      ],
      risk: "Medium"
    });

  };


  return (

    <section id="analyzer" className="container my-5">


      <h1 className="text-center fw-bold text-primary mb-4">
        Requirement Impact Analyzer
      </h1>



      <div className="card shadow p-4">


        <label className="form-label fw-bold">
          Enter Requirement Change
        </label>


        <textarea

          className="form-control"

          rows="5"

          placeholder="Example: Add online payment functionality"

          value={requirement}

          onChange={(e)=>setRequirement(e.target.value)}

        />



        <button

          className="btn btn-primary mt-3"

          onClick={analyzeRequirement}

        >

          Analyze Impact

        </button>



      </div>



      {
        result && (

          <div className="card shadow mt-4 p-4">


            <h3 className="text-success">
              Analysis Result
            </h3>


            <hr />


            <p>
              <b>Impact Level:</b> {result.impact}
            </p>


            <p>
              <b>Risk Level:</b> {result.risk}
            </p>



            <h5>
              Affected Modules:
            </h5>


            <ul>

              {
                result.modules.map((module,index)=>(

                  <li key={index}>
                    {module}
                  </li>

                ))
              }

            </ul>



          </div>

        )
      }



    </section>

  );

}


export default Analyzer;
